() => {
  // Click the visible element whose text matches "Skip" (mode "exact": exact | prefix | contains), right panel first.
  const want = "Skip", mode = "exact";
  const txt = (s) => (s || '').replace(/\s+/g, ' ').trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); const cs = getComputedStyle(e); return r.width > 0 && r.height > 0 && cs.visibility !== 'hidden' && cs.display !== 'none' && r.bottom > 0 && r.top < innerHeight; };
  const match = (s) => (mode === 'exact' ? s === want : mode === 'prefix' ? s.startsWith(want) : s.includes(want));
  const rank = { BUTTON: 0, A: 1, INPUT: 1, LABEL: 2 };
  const all = [...document.querySelectorAll('button,a,[role=button],[role=option],[role=radio],[role=tab],[role=menuitem],label,li,[tabindex],div,span,p')]
    .filter((e) => vis(e) && match(txt(e.innerText || e.getAttribute('aria-label') || e.value)));
  if (!all.length) return 'NOT FOUND: ' + want;
  all.sort((a, b) => (a.innerText.length - b.innerText.length) || ((rank[a.tagName] ?? 3) - (rank[b.tagName] ?? 3)));
  const el = all[0].closest('button,a,[role=button],[role=option],[role=radio],[role=tab],label') || all[0];
  if (el.disabled || el.getAttribute('aria-disabled') === 'true') return 'DISABLED: ' + txt(el.innerText).slice(0, 60);
  el.scrollIntoView({ block: 'center' });
  el.click();
  return 'clicked: ' + txt(el.innerText || el.getAttribute('aria-label')).slice(0, 70) + ' <' + el.tagName + '>';
}

async () => {
  const txt = (s) => (s || '').replace(/\s+/g, ' ').trim();
  const findStore = () => {
    if (window.__qaStore) return window.__qaStore;
    const root = document.getElementById('root');
    const key = root && Object.keys(root).find((k) => k.startsWith('__reactContainer$'));
    const stack = key ? [root[key]] : [];
    let n = 0;
    while (stack.length && n++ < 20000) {
      const f = stack.pop();
      if (!f) continue;
      const st = f.memoizedProps && f.memoizedProps.store;
      if (st && typeof st.getState === 'function') { window.__qaStore = st; return st; }
      stack.push(f.sibling, f.child);
    }
    return null;
  };
  const store = findStore();
  const pick = () => {
    const p = store.getState().rootStateUI.product;
    const o = p.productOptions, c = p.selectedProductConfig || {};
    return {
      SidePanels: o.SidePanels, L: o.SidePanelLeft, R: o.SidePanelRight,
      CountertopColor: o.CountertopColor, CountertopColorSku: o.CountertopColorSku,
      Thickness: o.Thickness, CountertopStyle: o.CountertopStyle, sinkType: o.sinkType,
      activeCabinetType: p.activeCabinetType, selectedSceneProduct: (p.selectedSceneProduct || '').slice(0, 40),
      dimH: p.selectedDimensions && p.selectedDimensions.height,
      cfgName: c.name || c.ProductType || c.productType || null, cfgDrawers: c.Drawers ?? null, cfgHeight: c.Height ?? null,
    };
  };
  if (store && !window.__qaUnsub) {
    window.__qaLog = [];
    let prev = JSON.stringify(pick());
    window.__qaLog.push({ t: 0, s: JSON.parse(prev) });
    const t0 = performance.now();
    window.__qaUnsub = store.subscribe(() => {
      const next = JSON.stringify(pick());
      if (next !== prev) { prev = next; window.__qaLog.push({ t: Math.round(performance.now() - t0), s: JSON.parse(next) }); }
    });
  }
  const body = txt(document.body.innerText);
  const price = body.match(/Total List Price\s*\$[\d,]+(\.\d+)?/);
  const out = { url: location.pathname + location.search, price: price ? price[0].replace('Total List Price', '').trim() : null,
    storeFound: !!store, state: store ? pick() : null };
  const w = document.querySelector('iframe') && document.querySelector('iframe').contentWindow;
  const api = w && w.ConfiguratorAPI;
  out.sceneReady = !!(api && api.composition);
  try {
    const all = api.composition.getAllProducts();
    out.products = Object.entries(all).map(([id, v]) => {
      const c = (v && v.config) || v || {};
      return { id: id.slice(0, 44), type: c.productType || c.ProductType || c.name || (v && v.productType) || null,
        Width: c.Width, Drawers: c.Drawers, SidePanel: c.SidePanel, SidePanelSide: c.SidePanelSide };
    });
  } catch (e) { out.productsErr = String(e).slice(0, 160); }
  try {
    const names = [];
    const walk = (e) => { if (!e) return; if (/sidepanel/i.test(e.name || '') && (e.enabled !== false)) names.push(e.name); (e.children || []).forEach(walk); };
    const app = w.pc && w.pc.Application && w.pc.Application.getApplication && w.pc.Application.getApplication();
    if (app) { walk(app.root); out.sidePanelEntities = names.length; out.sidePanelSample = [...new Set(names)].slice(0, 8); }
  } catch (e) { out.entErr = String(e).slice(0, 120); }
  out.dialogs = [...document.querySelectorAll('[role="dialog"],[role="alertdialog"]')].map((d) => txt(d.innerText).slice(0, 200));
  out.notices = [...document.querySelectorAll('[role="alert"],[role="status"],[class*="toast" i],[class*="notice" i],[class*="notification" i]')].map((d) => txt(d.innerText)).filter(Boolean).slice(0, 6);
  out.guard = { on: !!window.__qaWriteGuard, blocked: window.__blockedWrites || [] };
  return out;
}

